response.text:
{
  "title": "Sticking to Treatment",
  "perWatchSecond": 2,
  "levels": [
    {
      "kind": "hook",
      "finding": 0,
      "title": "The 52 percent line",
      "goal": "See how crossing the 52% adherence threshold stops the epidemic.",
      "control": {
        "parameter": "theta",
        "label": "Treatment adherence",
        "lowEnd": "0.30",
        "highEnd": "0.70"
      },
      "watch": "cq",
      "whatIf": {
        "prompt": "What if 60% of patients stick to treatment instead of 50%?",
        "parameter": "theta",
        "value": 0.6
      },
      "difference": {
        "compartment": "cq",
        "summary": "peak",
        "at": null,
        "time": 80,
        "relation": "lower",
        "by": 0.008
      },
      "effect": "Raising adherence from 50% to 60% lowers the peak of quit-treatment patients by more than 0.008.",
      "prediction": {
        "prompt": "Will the quit-treatment peak be higher or lower when adherence rises to 60%?",
        "claimed": "lower",
        "other": "higher"
      },
      "passage": {
        "title": "Adherence threshold",
        "quote": "an adherence level exceeding 52% causes the reproduction number to drop below 1, curtailing further spread."
      },
      "carryForward": "Above 52% adherence the epidemic dies out; below it, quit-treatment patients keep the virus circulating."
    },
    {
      "kind": "result",
      "finding": 4,
      "title": "The quit-treatment engine",
      "goal": "Show that quit-treatment patients drive more spread than any other infected group.",
      "control": {
        "parameter": "beta3",
        "label": "Transmission from quit patients",
        "lowEnd": "0.01",
        "highEnd": "0.10"
      },
      "watch": "s",
      "whatIf": {
        "prompt": "What if quit-treatment patients spread the virus twice as fast?",
        "parameter": "beta3",
        "value": 0.1
      },
      "difference": {
        "compartment": "s",
        "summary": "at",
        "at": 120,
        "time": 120,
        "relation": "lower",
        "by": 0.02
      },
      "effect": "Doubling the transmission rate from quit-treatment patients lowers the susceptible share at year 120 by more than 0.02.",
      "prediction": {
        "prompt": "Will more or fewer susceptibles remain at year 120 if quit patients spread twice as fast?",
        "claimed": "fewer",
        "other": "more"
      },
      "passage": {
        "title": "Strongest influence",
        "quote": "$β_{3}$ exerts the strongest influence on the reproduction number."
      },
      "carryForward": "Quit-treatment patients are the main engine of spread; their transmission rate matters more than any other infected group."
    },
    {
      "kind": "result",
      "finding": 3,
      "title": "Faster acute recovery",
      "goal": "Show that clearing the acute stage faster shrinks the chronic pipeline.",
      "control": {
        "parameter": "r2",
        "label": "Leaving the acute stage",
        "lowEnd": "0.10",
        "highEnd": "0.30"
      },
      "watch": "cq",
      "whatIf": {
        "prompt": "What if acutely infected patients leave the acute stage twice as fast?",
        "parameter": "r2",
        "value": 0.326
      },
      "difference": {
        "compartment": "cq",
        "summary": "peak",
        "at": null,
        "time": 80,
        "relation": "lower",
        "by": 0.003
      },
      "effect": "Doubling the rate of leaving the acute stage lowers the peak of quit-treatment patients by more than 0.003.",
      "prediction": {
        "prompt": "Will the quit-treatment peak be higher or lower if acute patients clear the stage faster?",
        "claimed": "lower",
        "other": "higher"
      },
      "passage": {
        "title": "Synergistic impact",
        "quote": "Our model unraveled the synergistic impact of simultaneously enhancing the recovery rate of acutely infected individuals and treatment adherence on reducing $ℛ_{0}$."
      },
      "carryForward": "Faster acute recovery shrinks the pipeline into chronic infection, reducing the quit-treatment reservoir that fuels spread."
    },
    {
      "kind": "result",
      "finding": 6,
      "title": "The 0.19 recovery threshold",
      "goal": "Show that raising on-treatment recovery to about 0.19 crosses the epidemic threshold.",
      "control": {
        "parameter": "rho",
        "label": "Recovery on treatment",
        "lowEnd": "0.01",
        "highEnd": "0.25"
      },
      "watch": "c",
      "whatIf": {
        "prompt": "What if the on-treatment recovery rate rises to 0.19?",
        "parameter": "rho",
        "value": 0.19
      },
      "difference": {
        "compartment": "c",
        "summary": "at",
        "at": 40,
        "time": 80,
        "relation": "lower",
        "by": 0.001
      },
      "effect": "Raising the on-treatment recovery rate to 0.19 lowers the chronic-infection share at year 40 by more than 0.001.",
      "prediction": {
        "prompt": "Will the chronic-infection share at year 40 be higher or lower at a recovery rate of 0.19?",
        "claimed": "lower",
        "other": "higher"
      },
      "passage": {
        "title": "Recovery threshold",
        "quote": "When ρ approaches a value of approximately 0.19, we observe that $ℛ_{0}$ falls below 1."
      },
      "carryForward": "At a recovery rate near 0.19 the epidemic threshold is crossed and the disease dies out, just as with high adherence."
    }
  ],
  "limits": [
    "Each level runs two worlds side by side; only one parameter or starting value differs.",
    "The control slider sets a rate parameter; the What-if changes exactly one value.",
    "Predict before the What-if world runs, then check whether the curves part as you expected.",
    "Compartments are shares of the population, so 0.05 means 5% of people.",
    "A compartment smaller than three figures in the town of 120 is shown through a magnifying lens."
  ]
}
